<template><PageShell title="Analytics & Reports" subtitle="A lightweight city-wide operational summary derived from real request, offer, mission, and fleet records." icon="lucide:chart-no-axes-combined" eyebrow="Platform Executive"><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Incidents (30 days)" :value="stats.incidents_30d"/><Stat label="Completed incidents" :value="stats.completed"/><Stat label="Active missions" :value="stats.active_missions"/><Stat label="City fleet" :value="stats.fleet_total"/></div><div class="mt-6 grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><section class="rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]"><h2 class="font-black dark:text-white">Offer outcomes</h2><div class="mt-4 space-y-3"><Bar label="Accepted" :value="stats.offers_accepted" :total="offerTotal" tone="green"/><Bar label="Declined" :value="stats.offers_declined" :total="offerTotal" tone="amber"/><Bar label="Timed out" :value="stats.offers_timed_out" :total="offerTotal" tone="red"/></div><h2 class="mt-7 font-black dark:text-white">Severity · last 30 days</h2><div class="mt-3 grid grid-cols-2 gap-2"><div v-for="s in severity" :key="s.severity" class="rounded-2xl bg-base-200 p-3"><p class="text-lg font-black dark:text-white">{{ s.count }}</p><p class="text-xs font-bold text-slate-500">{{ pretty(s.severity) }}</p></div></div></section><section class="overflow-hidden rounded-3xl border border-base-300 bg-base-100 shadow-sm dark:border-white/10 dark:bg-[#071829]"><div class="p-5"><h2 class="font-black dark:text-white">Organization response summary</h2><p class="mt-1 text-xs text-slate-400">Average response is calculated only when arrival timestamps exist.</p></div><div class="overflow-x-auto"><table class="w-full min-w-[650px] text-left text-sm"><thead class="bg-base-200/70 text-[.65rem] font-black uppercase text-slate-400"><tr><th class="px-5 py-3">Organization</th><th class="px-5 py-3">Missions</th><th class="px-5 py-3">Completed</th><th class="px-5 py-3">Avg response</th></tr></thead><tbody class="divide-y divide-base-300"><tr v-for="o in organizations" :key="o.name"><td class="px-5 py-4 font-bold dark:text-white/70">{{ o.name }}</td><td class="px-5 py-4">{{ o.missions }}</td><td class="px-5 py-4">{{ o.completed }}</td><td class="px-5 py-4">{{ o.avg_response_minutes?`${o.avg_response_minutes} min`:'—' }}</td></tr></tbody></table></div></section></div></PageShell></template>
<script setup>import{computed,defineComponent,h,onMounted,ref}from'vue';import PageShell from '@/components/management/PageShell.vue';import{fetchPlatformAnalytics}from'@/services/adminCompletion';const stats=ref({}),severity=ref([]),organizations=ref([]),offerTotal=computed(()=>Number(stats.value.offers_accepted||0)+Number(stats.value.offers_declined||0)+Number(stats.value.offers_timed_out||0));const Stat=defineComponent({props:{label:String,value:[String,Number]},setup:p=>()=>h('article',{class:'rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]'},[h('p',{class:'text-2xl font-black dark:text-white'},String(p.value??0)),h('p',{class:'mt-1 text-xs font-bold text-slate-500'},p.label)])});const Bar=defineComponent({props:{label:String,value:[String,Number],total:Number,tone:String},setup:p=>()=>h('div',[h('div',{class:'flex justify-between text-xs font-bold text-slate-500'},[h('span',p.label),h('span',String(p.value??0))]),h('div',{class:'mt-1 h-2 rounded-full bg-base-200'},[h('div',{class:['h-2 rounded-full',p.tone==='green'?'bg-emerald-500':p.tone==='amber'?'bg-amber-500':'bg-red-500'],style:{width:`${p.total?Math.min(100,(Number(p.value||0)/p.total)*100):0}%`}})])])});const pretty=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase());onMounted(async()=>{const d=await fetchPlatformAnalytics();stats.value=d.stats||{};severity.value=d.severity||[];organizations.value=d.organizations||[]})</script>
